    for _ in 0.. {
        let mut tasks = Vec::new();
        for _ in 0..100 {
            let (a, mut b) = tokio::sync::mpsc::channel::<u32>(1);
            let b = tokio::spawn(async move {
                b.is_empty();
                b.recv().await;
            });
            let a = tokio::spawn(async move {
                let mut a = PollSender::new(a);
                std::future::poll_fn(|cx| a.poll_reserve(cx)).await.unwrap();
                a.send_item(3).unwrap();
            });

            tasks.push(a);
            tasks.push(b);
